def assign_bugs(n, m, s, a, b, c):
    # Sort students by their ability levels and bugs by their complexities
    students = sorted(range(n), key=lambda x: b[x])
    bugs = sorted(range(m), key=lambda x: a[x])

    # Initialize the result list and pass count
    result = [-1] * m
    total_passes = 0

    # Try to assign bugs to students
    for i in range(m):
        for j in range(n):
            if result[bugs[i]] == -1 and b[students[j]] >= a[bugs[i]]:
                if total_passes + c[students[j]] <= s:
                    result[bugs[i]] = students[j]
                    total_passes += c[students[j]]
                    break

    # Check if all bugs were assigned
    if -1 in result:
        return "NO"
    else:
        return "YES\n" + " ".join(map(str, result))

