import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
m = int(data[1])
s = int(data[2])

bugs = list(map(int, data[3:3+m]))
students = list(map(int, data[3+m:3+2*m]))
passes = list(map(int, data[3+2*m:]))

bugs.sort()
students.sort()

dp = [[float('inf')] * (s + 1) for _ in range(m + 1)]
dp[0][0] = 0

for i in range(1, m + 1):
    for j in range(s + 1):
        dp[i][j] = dp[i - 1][j]
        if j >= passes[i - 1]:
            dp[i][j] = min(dp[i][j], dp[i - 1][j - passes[i - 1]] + 1)

if dp[m][s] == float('inf'):
    print("NO")
else:
    print("YES")
    assignment = [0] * m
    j = s
    for i in range(m - 1, -1, -1):
        if dp[i][j] != dp[i - 1][j]:
            assignment[i] = 1
            j -= passes[i]

    for i in range(m):
        if assignment[i] == 0:
            assignment[i] = 2

    for i in range(m):
        if assignment[i] == 0:
            assignment[i] = 3

    print(*assignment)
